using System;
using System.Collections.Generic;

// PROGRAM: Simulasi Navigasi B-Tree Simpul Sederhana
public class BTreeNode
{
    public List<int> Keys { get; } = new();
    public List<BTreeNode> Children { get; } = new();
    public bool IsLeaf => Children.Count == 0;

    public int SearchKey(int targetKey)
    {
        // Binary search internal di dalam satu halaman simpul (In-Memory)
        int idx = Keys.BinarySearch(targetKey);
        return idx;
    }
}

public class Program
{
    public static void Main()
    {
        // Simulasi pembuatan Root simpul B-Tree berkapasitas banyak kunci
        var root = new BTreeNode();
        root.Keys.AddRange(new[] { 10, 50, 100, 250, 500 });

        Console.WriteLine($"=== SIMULASI NODE B-TREE ===");
        Console.WriteLine($"Kapasitas Kunci di Node Root: {root.Keys.Count}");

        int target = 100;
        int pos = root.SearchKey(target);
        Console.WriteLine($"Pencarian Kunci {target}: Ditemukan di indeks posisi {pos} pada node ini.");
    }
}

