using System;

public class BTreeNavigator
{
    public static int FindChildSlotIndex(int[] nodeKeys, int targetKey)
    {
        if (nodeKeys == null || nodeKeys.Length == 0) return 0;

        for (int i = 0; i < nodeKeys.Length; i++)
        {
            if (targetKey < nodeKeys[i])
            {
                return i;
            }
        }

        return nodeKeys.Length;
    }

    public static void Main()
    {
        int[] keys = { 10, 20, 30 };
        Console.WriteLine($"Target 5  -> Slot: {FindChildSlotIndex(keys, 5)}");
        Console.WriteLine($"Target 15 -> Slot: {FindChildSlotIndex(keys, 15)}");
        Console.WriteLine($"Target 35 -> Slot: {FindChildSlotIndex(keys, 35)}");
    }
}
